import z from "zod"

// generated by the `imported` config; tests/importingVariants.ts references these instead of
// hoisting its own copies (see tests/corpus.config.ts)

export const sharedLocale = z.enum(["en-US", "fr-CA"])

export const sharedChannel = z.discriminatedUnion("kind", [
  z.object({ kind: z.literal("email"), to: z.string() }),
  z.object({ kind: z.literal("sms"), phone: z.string() }),
])

export const sharedSlot = z.object({ priority: z.int(), label: z.string() })

// exported but NOT named in the import, so a structural match still hoists locally
export const notImported = z.enum(["x", "y"])
